 if(j.type==='raid'){const sites=WLD.driveNodes.filter(n=>dist(n,player)>900&&dist(n,player)<2100&&dist(n,places[6])>500),site=pick(sites.length?sites:WLD.driveNodes),spot=openSpot(site,80);job.site=spot;job.target=spot;job.barrels=[];for(let i=0;i<6;i++){const a=i*TAU/6,x=spot.x+Math.cos(a)*rand(28,52),y=spot.y+Math.sin(a)*rand(28,52);if(blocked(x,y,8))continue;const b={type:'xbarrel',x,y,a:0,r:8,temp:true};addProp(b);job.barrels.push(b)}if(job.barrels.length<3){for(let i=0;i<4;i++){const b={type:'xbarrel',x:site.x+rand(-30,30),y:site.y+rand(-30,30),a:0,r:8,temp:true};addProp(b);job.barrels.push(b)}}for(let i=0;i<3;i++){const e={x:spot.x+rand(-70,70),y:spot.y+rand(-70,70),a:0,hp:75,maxHp:75,fire:rand(1.5,3),hit:0,job:true};if(blocked(e.x,e.y,9)){e.x=spot.x;e.y=spot.y}enemies.push(e);job.targets.push(e)}job.info='Blow up the red barrels at the rival still. Shoot them or ram them, then get clear.';legs=routeLen(player,site);extra+=110;toast('Red barrels explode. Shoot them from a safe distance.')}
