const HEADLINES={bootleg:['MYSTERY CARGO KEEPS DRY COUNTY WET','SPEAKEASIES RESTOCKED OVERNIGHT','WHO IS BEHIND THE MIDNIGHT DELIVERIES?'],rival:['GANG FEUD ERUPTS DOWNTOWN','RIVAL CREW ROUTED, LEDGER MISSING','SHOTS FIRED NEAR LOCAL CLUB'],wheelman:['LUXURY COUPE VANISHES FROM CLUB CURB','STOLEN CAR OUTRUNS ENTIRE SQUAD'],hijack:['WHISKEY TRUCK WRECKED ON COUNTY ROAD','HIJACKERS STRIKE AGAIN'],raid:['ILLEGAL STILL GOES UP IN FLAMES','EXPLOSIONS ROCK THE OUTSKIRTS'],getaway:['DARING GETAWAY STUNS POLICE','CASH ROOM CLEANED OUT IN MINUTES']};
