function completeJob(){if(!job)return;const completed=job;combo++;comboTimer=180;save.stats.bestStreak=Math.max(save.stats.bestStreak,combo);const bonus=Math.min(5,combo-1)*.1;let pay=Math.floor(completed.pay*(1+bonus));const cargo=completed.type==='bootleg'&&completed.cases<12;if(cargo)pay=Math.floor(pay*Math.max(.25,completed.cases/12));const timeBonus=Math.min(Math.floor(completed.pay*.35),Math.floor(Math.max(0,completed.time||0)*1.2));pay+=timeBonus;save.cash+=pay;save.stats.earnings+=pay;save.xp+=completed.xp;save.jobs++;refreshDaily();save.daily.done++;job=null;removeTempProps();enemies=enemies.filter(e=>!e.job);for(const c of cars){c.mission=false;if(c.missionTruck){c.missionTruck=false;if(!c.dead&&!c.burning)c.ai='traffic'}}player.reserve=Math.max(player.reserve,weapons[save.weapon].reserve);player.hp=Math.min(100,player.hp+25);sound('cash');toast('JOB COMPLETE · '+money(pay)+(bonus>0?' · '+Math.round(bonus*100)+'% streak':'')+(timeBonus>0?' · '+money(timeBonus)+' time bonus':'')+(cargo?' · '+completed.cases+'/12 cases':''));showPaper({kicker:'EXTRA · THE MT. MORRIS MESSENGER',headline:pick(HEADLINES[completed.type]||HEADLINES.bootleg),deck:DECKS[completed.type]||'',fact:nextFact()});generateJobs();updateObjective();persist();}
function failJob(reason){if(!job)return;job=null;removeTempProps();enemies=enemies.filter(e=>!e.job);for(const c of cars){c.mission=false;if(c.missionTruck){c.missionTruck=false;if(!c.dead&&!c.burning)c.ai='traffic'}}combo=0;toast(reason+' · New contracts are available.');updateObjective();generateJobs()}
